def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find a solid, single-color divider.
    divider = None
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if vals[0] != 0 and all(v == vals[0] for v in vals):
            divider = ("v", c)
            break
    if divider is None:
        for r in range(h):
            vals = grid[r]
            if vals[0] != 0 and all(v == vals[0] for v in vals):
                divider = ("h", r)
                break
    if divider is None:
        return out

    kind, pos = divider
    if kind == "v":
        left_count = sum(grid[r][c] != 0 for r in range(h) for c in range(pos))
        right_count = sum(grid[r][c] != 0 for r in range(h) for c in range(pos + 1, w))
        source_left = left_count >= right_count

        for r in range(h):
            if source_left:
                runs = []
                c = 0
                while c < pos:
                    if grid[r][c] == 0:
                        c += 1
                        continue
                    color, start = grid[r][c], c
                    while c < pos and grid[r][c] == color:
                        c += 1
                    runs.append((start, c, color))
                runs.sort(key=lambda run: run[1], reverse=True)
                for start, end, color in runs:
                    length = end - start
                    for c in range(pos + 1, w, length):
                        if out[r][c] == 0:
                            out[r][c] = color
            else:
                runs = []
                c = pos + 1
                while c < w:
                    if grid[r][c] == 0:
                        c += 1
                        continue
                    color, start = grid[r][c], c
                    while c < w and grid[r][c] == color:
                        c += 1
                    runs.append((start, c, color))
                runs.sort(key=lambda run: run[0])
                for start, end, color in runs:
                    length = end - start
                    for c in range(pos - 1, -1, -length):
                        if out[r][c] == 0:
                            out[r][c] = color
    else:
        above_count = sum(grid[r][c] != 0 for r in range(pos) for c in range(w))
        below_count = sum(grid[r][c] != 0 for r in range(pos + 1, h) for c in range(w))
        source_above = above_count >= below_count

        for c in range(w):
            if source_above:
                runs = []
                r = 0
                while r < pos:
                    if grid[r][c] == 0:
                        r += 1
                        continue
                    color, start = grid[r][c], r
                    while r < pos and grid[r][c] == color:
                        r += 1
                    runs.append((start, r, color))
                runs.sort(key=lambda run: run[1], reverse=True)
                for start, end, color in runs:
                    length = end - start
                    for r in range(pos + 1, h, length):
                        if out[r][c] == 0:
                            out[r][c] = color
            else:
                runs = []
                r = pos + 1
                while r < h:
                    if grid[r][c] == 0:
                        r += 1
                        continue
                    color, start = grid[r][c], r
                    while r < h and grid[r][c] == color:
                        r += 1
                    runs.append((start, r, color))
                runs.sort(key=lambda run: run[0])
                for start, end, color in runs:
                    length = end - start
                    for r in range(pos - 1, -1, -length):
                        if out[r][c] == 0:
                            out[r][c] = color

    return out
